-- ============================================================================
-- SEED — Fluxo de Processos E-commerce (primeira versão publicada)
-- ============================================================================
-- Roda no SQL Editor do Supabase do Report E-commerce (projeto
-- "Report - Operacional"). Insere a PRIMEIRA linha de dashboard_snapshots para
-- pagina='ecom_fluxo' — sem essa linha a tela mostra "Nenhuma versão do fluxo
-- publicada ainda" (ver ecom-fluxo.js, carregarDados()).
--
-- É o ESQUELETO do fluxo: as 5 fases do fluxo principal (Recebimento,
-- Armazenagem, Separação, Packing, Expedição) + a Reversa, cada uma com uma
-- "Primeira etapa". O conteúdo real do processo é montado pelo admin na
-- própria tela (✏️ Editar fluxo → Salvar alterações), sem SQL.
--
-- Rode migracao_rls_ecom_fluxo.sql antes (ou junto): sem ela o operador não lê
-- esta página. Cada rodada deste arquivo cria uma NOVA versão (o app nunca dá
-- UPDATE) — só rode de novo se quiser mesmo voltar ao esqueleto.
-- ============================================================================

insert into dashboard_snapshots (pagina, tipo_snapshot, data_snapshot, gerado_em, payload)
values ('ecom_fluxo', 'manual', (now() at time zone 'utc')::date, now() at time zone 'utc', $seed_ecom_fluxo${"versao_schema": 1, "titulo_pagina": "Fluxo de Processos — E-commerce", "setores": ["Armazenagem", "Estoque", "Expedição", "Fiscal", "Packing", "Qualidade", "Recebimento", "Reversa", "Separação", "Transporte"], "lanes": [{"id": "principal", "titulo": "Fluxo principal — Recebimento → Armazenagem → Separação → Packing → Expedição", "sub": "Da chegada da mercadoria no CD até o pedido do e-commerce entregue à transportadora. Cada fase recomeça sua própria numeração — é tratada como um processo à parte.", "fases": [{"id": "receb", "titulo": "Recebimento", "blocos": [["step", "1"]]}, {"id": "armaz", "titulo": "Armazenagem", "blocos": [["step", "1"]]}, {"id": "separ", "titulo": "Separação", "blocos": [["step", "1"]]}, {"id": "pack", "titulo": "Packing", "blocos": [["step", "1"]]}, {"id": "exped", "titulo": "Expedição", "blocos": [["step", "1"]]}]}, {"id": "reversa", "titulo": "Fluxo de Reversa — Devolução do cliente", "sub": "Disparado pela chegada de uma devolução de pedido do e-commerce, não pela sequência acima.", "fases": [{"id": "rever", "titulo": "Reversa", "blocos": [["step", "1"]]}]}], "nos": {"receb:1": {"n": "1", "n_orig": null, "novo": false, "extraido_de": null, "fase": "receb", "nome": "Primeira etapa", "nome_orig": "Primeira etapa", "tipo": "principal", "subtipo": null, "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "Etapa inicial — edite pelo modo edição para descrever o processo.", "original": "", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "boxin"}, "armaz:1": {"n": "1", "n_orig": null, "novo": false, "extraido_de": null, "fase": "armaz", "nome": "Primeira etapa", "nome_orig": "Primeira etapa", "tipo": "principal", "subtipo": null, "resp": "Armazenagem", "orig": "—", "dest": "—", "resumo": "Etapa inicial — edite pelo modo edição para descrever o processo.", "original": "", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "shelf"}, "separ:1": {"n": "1", "n_orig": null, "novo": false, "extraido_de": null, "fase": "separ", "nome": "Primeira etapa", "nome_orig": "Primeira etapa", "tipo": "principal", "subtipo": null, "resp": "Separação", "orig": "—", "dest": "—", "resumo": "Etapa inicial — edite pelo modo edição para descrever o processo.", "original": "", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "lupa"}, "pack:1": {"n": "1", "n_orig": null, "novo": false, "extraido_de": null, "fase": "pack", "nome": "Primeira etapa", "nome_orig": "Primeira etapa", "tipo": "principal", "subtipo": null, "resp": "Packing", "orig": "—", "dest": "—", "resumo": "Etapa inicial — edite pelo modo edição para descrever o processo.", "original": "", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "boxx"}, "exped:1": {"n": "1", "n_orig": null, "novo": false, "extraido_de": null, "fase": "exped", "nome": "Primeira etapa", "nome_orig": "Primeira etapa", "tipo": "principal", "subtipo": null, "resp": "Expedição", "orig": "—", "dest": "—", "resumo": "Etapa inicial — edite pelo modo edição para descrever o processo.", "original": "", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "truck"}, "rever:1": {"n": "1", "n_orig": null, "novo": false, "extraido_de": null, "fase": "rever", "nome": "Primeira etapa", "nome_orig": "Primeira etapa", "tipo": "principal", "subtipo": null, "resp": "Reversa", "orig": "—", "dest": "—", "resumo": "Etapa inicial — edite pelo modo edição para descrever o processo.", "original": "", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "ret"}}, "armazens": [], "pendencias": []}$seed_ecom_fluxo$::jsonb);
